-- the old 'Back Squat' / 'Romanian Deadlift' names in PR lists -> library names
update posts set prs = array(select case p when 'Back Squat' then 'Squat (Barbell)' when 'Romanian Deadlift' then 'Romanian Deadlift (Barbell)' when 'Bench Press' then 'Bench Press (Barbell)' when 'Deadlift' then 'Deadlift (Barbell)' else p end from unnest(prs) p);
